    "start_dosing",
    {state:true},
    5000
);

settings.cellContentFunction:
var deviceType = value;
var color = '#fff';
var textColor = ''
var bgColor = ''
var text = ''
switch (deviceType) {
    case 'true':
        color = 'green';
        text = 'Active';
        bgColor = '#69f0ae';
        textColor = '#2e7d32';
        break;
    case 'false':
        color = 'red';
        text = 'Inactive';
        bgColor = '#ef9a9a';
        textColor = '#d50000';
        break;
    case 'default':
        color = '';
        text = '';
        break;
}
return `<div style="border: 2px solid ${color}; border-radius: 10px; padding: 5px; background-color: ${bgColor}; color:${textColor}; text-align: center;">  ${text} </div>`;

settings.cellStyleFunction:
