if (tankLevel > 5 && tankLevel < 8) {
    return {
        "text-align":"center",
        "background-color": "#FFD580"
    };
} else if (tankLevel < 5) {
    return {
        "text-align":"center",
        "background-color": "#FF474C"
    };
} else {
    return {
        "text-align":"center",
        "background-color": "#90EE90"
    }
}

